-- @function public.hunt_v2_start(text, bigint[])
-- md5: a5ef6f142d4e8d534b6ebb340320bdb9   (md5(replace(pg_get_functiondef('public.hunt_v2_start(text, bigint[])'::regprocedure), chr(13), '')))
